package com.cpf.starter.security.session.valkey; import java.time.Duration; import org.springframework.boot.context.properties.ConfigurationProperties;
@ConfigurationProperties("cpf.security.session.valkey") public class CpfValkeySessionProperties { private boolean enabled=false; private String keyPrefix="cpf:session:"; private Duration defaultTtl=Duration.ofMinutes(30); private int maxConcurrentSessions=5; public boolean isEnabled(){return enabled;} public void setEnabled(boolean v){enabled=v;} public String getKeyPrefix(){return keyPrefix;} public void setKeyPrefix(String v){keyPrefix=v;} public Duration getDefaultTtl(){return defaultTtl;} public void setDefaultTtl(Duration v){defaultTtl=v;} public int getMaxConcurrentSessions(){return maxConcurrentSessions;} public void setMaxConcurrentSessions(int v){maxConcurrentSessions=v;} }
